/**
 * Behavior tests for the opt-out head check generated by OptOut::script(),
 * run with `npm test` (needs PHP on the PATH).
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { JSDOM, VirtualConsole } from 'jsdom';

const fixture = fileURLToPath( new URL( './fixtures/render-optout-check.php', import.meta.url ) );
const render = ( settings ) => execFileSync( 'php', [ fixture, JSON.stringify( settings ) ], { encoding: 'utf8' } );

function run( settings, { cookie = '', dnt = false, gpc = false } = {} ) {
	const script = render( settings );
	const dom = new JSDOM( '<!doctype html><body></body>', { url: 'https://example.com/', runScripts: 'outside-only', virtualConsole: new VirtualConsole() } );
	const win = dom.window;
	if ( cookie ) {
		win.document.cookie = cookie;
	}
	Object.defineProperty( win.navigator, 'doNotTrack', { value: dnt ? '1' : null } );
	Object.defineProperty( win.navigator, 'globalPrivacyControl', { value: gpc } );
	win.eval( script );
	return { win, script };
}

const OPTOUT = { measurement_id: 'G-TEST1234', allow_optout: true };
const DNT = { measurement_id: 'G-TEST1234', respect_dnt: true };
const disabled = ( win ) => win.gainwpOptOut === true && win[ 'ga-disable-G-TEST1234' ] === true;

test( 'a stored opt-out is honored after the site turns opt-out off', () => {
	const off = { measurement_id: 'G-TEST1234' };
	assert.ok( disabled( run( off, { cookie: 'gainwp_optout=1' } ).win ) );
	assert.ok( disabled( run( off, { cookie: 'ga-disable-UA-12345-1=true' } ).win ) );
	assert.equal( disabled( run( off ).win ), false );
	assert.equal( typeof run( off ).win.gaOptout, 'undefined', 'gaOptout() needs opt-out on' );
} );

test( 'visitors without an opt-out are tracked', () => {
	assert.equal( disabled( run( OPTOUT ).win ), false );
} );

test( 'a 6.x opt-out cookie stops tracking', () => {
	assert.ok( disabled( run( OPTOUT, { cookie: 'gainwp_optout=1' } ).win ) );
} );

test( 'a 5.x opt-out cookie still stops tracking', () => {
	assert.ok( disabled( run( OPTOUT, { cookie: 'ga-disable-UA-12345-1=true' } ).win ) );
} );

test( 'similar cookie names are not mistaken for an opt-out', () => {
	assert.equal( disabled( run( OPTOUT, { cookie: 'xgainwp_optout=1' } ).win ), false );
	assert.equal( disabled( run( OPTOUT, { cookie: 'xga-disable-UA-1-1=true' } ).win ), false );
} );

test( 'Do Not Track and Global Privacy Control are honored only when enabled', () => {
	assert.ok( disabled( run( DNT, { dnt: true } ).win ) );
	assert.ok( disabled( run( DNT, { gpc: true } ).win ) );
	assert.equal( disabled( run( OPTOUT, { dnt: true } ).win ), false );
} );

test( 'gaOptout() exists while the page loads when opt-out is on, as in 5.x', () => {
	const { win } = run( OPTOUT );
	assert.equal( typeof win.gaOptout, 'function' );
	win.gaOptout();
	assert.ok( disabled( win ) );
	assert.match( win.document.cookie, /gainwp_optout=1/ );
	assert.deepEqual( Array.from( win.dataLayer, ( e ) => ( { ...e } ) ), [ { event: 'gainwp_optout' } ] );
} );

test( 'gaOptout() is not defined when only Do Not Track is on', () => {
	assert.equal( typeof run( DNT ).win.gaOptout, 'undefined' );
} );

test( 'without a Measurement ID only the tag flag is set', () => {
	const { win } = run( { allow_optout: true }, { cookie: 'gainwp_optout=1' } );
	assert.equal( win.gainwpOptOut, true );
	assert.equal( Object.keys( win ).some( ( k ) => k.startsWith( 'ga-disable-' ) ), false );
} );
